window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[226]={"id":"226","numero":226,"titre":"Maladie thrombo-embolique veineuse — TVP & EP","objectifs":[{"id":"226-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","contenu":"<div class=\"notion-course\"><p>La <span>maladie thrombo-embolique veineuse (MTEV)</span> est une entité unique dont les <strong>deux manifestations cliniques</strong> sont la <span>TVP</span> (≈ 2/3 des cas) et l'<span>EP</span> (≈ 1/3). C'est le symptôme qui guide la définition de chacune.</p>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-yellow_bg\">TVP</span></span></td><td>Obstruction <span>thrombotique</span> d'un tronc veineux <strong><span class=\"nc-yellow_bg\">profond</span></strong>, localisée le plus souvent aux <span>membres inférieurs</span></td></tr>\n          <tr><td><span>TVP <span class=\"nc-yellow_bg nc-bold\">proximale</span></span></td><td>Thrombose <strong>sus-poplitée</strong> : veines poplitée, fémorale, iliaque, cave — <span>risque d'EP élevé</span></td></tr>\n          <tr><td><span>TVP distale</span></td><td>Thrombose <strong>sous-poplitée</strong> : veines jambières (<span class=\"nc-pink_bg\">tibiale antérieure</span> et postérieure, <span class=\"nc-pink_bg\">fibulaire</span>) et surales (<span class=\"nc-pink_bg\">soléaire</span>, <span class=\"nc-pink_bg\">gastrocnémienne</span>)</td></tr>\n          <tr><td><span>EP</span></td><td>Obstruction des <span>artères pulmonaires</span> ou de leurs branches par des <span>thrombus</span></td></tr>\n          <tr><td><span><span class=\"nc-red_bg\">EP à haut risque</span></span></td><td>EP définie par la présence d'un <span><span class=\"nc-red_bg\">état de choc</span></span> — forme rare (≈ <span>5 %</span>) mais <span><span class=\"nc-red nc-bold\">mortalité 25-50 %</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Épidémiologie</span>.</strong> <span>Incidence</span> de la <span class=\"nc-red_bg\">MTEV</span> <span>1-2/1000/an</span>, en augmentation avec l'âge (<span>1/100</span> après <span>75 ans</span> contre <span>1/10 000</span> avant <span>40 ans</span>). Maladie grave : <span>mortalité à 3 mois 5-10 %</span> ; chaque année <span>35 000</span> patients sont hospitalisés en France pour une EP, avec une <span>mortalité hospitalière de 5 %</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"nc-red_bg\">EP à haut risque</span>.</strong> Le critère définissant n'est pas la taille du <span><span class=\"nc-red nc-bold\">thrombus</span></span> mais le <span>retentissement hémodynamique</span> : peu importe le reste, une <span>PAS <span class=\"nc-red nc-bold\">&lt; 90 mmHg</span></span> classe l'EP en <strong>haut risque</strong>.</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"226-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","contenu":"<div class=\"notion-course\"><p>La MTEV est une <span>maladie multifactorielle</span>. Les <span class=\"nc-brown_bg\">facteurs</span> favorisants se croisent selon deux axes : <strong>transitoire <span>vs</span> persistant</strong> et <strong>majeur <span>vs</span> mineur</strong>. Cette <span>classification</span> commande la durée du <span class=\"nc-purple_bg\">traitement </span><span><span class=\"nc-purple_bg\">anticoagulant</span></span>.</p>\n      <table>\n        <thead><tr><th></th><th>Majeurs</th><th>Mineurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Transitoires</strong></td>\n            <td>Œstrogènes, <span class=\"nc-pink_bg\">grossesse</span> et <span class=\"nc-pink_bg\">post-partum</span> sont des <span class=\"nc-brown_bg\">facteurs</span> transitoires de MTEV ; leur classification en facteur majeur ou mineur dépend du référentiel et du contexte, et ne doit <span class=\"nc-red nc-bold\">pas</span> être confondue avec celle d’une chirurgie majeure.</td>\n            <td>\n              <span>Traumatisme d'un MI non plâtré</span> avec mobilité réduite <span>≥ 3 jours</span> &lt;<span> 2 mois</span> ; <span>immobilisation &lt; 3 jours</span> &lt;<span> 3 mois</span> ; <span><span class=\"nc-green_bg\">voyage &gt; 6 h</span></span> ; <span class=\"nc-green_bg\">traitement par </span><span><span class=\"nc-green_bg\">EPO</span></span> ; <span>voie veineuse centrale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Persistants</strong></td>\n            <td>\n              <span><span class=\"nc-red_bg\">Cancer actif</span></span> ; <span class=\"nc-orange_bg\">thrombophilie</span> majeure : <span class=\"nc-red_bg\">déficit en </span><span><span class=\"nc-red_bg\">antithrombine</span></span>, <span><span class=\"nc-red_bg\">SAPL</span></span> <em>(seule <span class=\"nc-yellow_bg\">thrombophilie </span><span><span class=\"nc-yellow_bg\">acquise</span></span>)</em>\n            </td>\n            <td>\n              <span>Âge <span class=\"nc-pink nc-bold\">&gt; 65 ans</span></span> ; <span><span class=\"nc-blue_bg\">obésité</span></span>, <span><span class=\"nc-blue_bg\">syndrome néphrotique</span></span>, HPN ; <span><span class=\"nc-blue_bg\">MICI</span></span>, <span class=\"nc-blue_bg\">maladies inflammatoires chroniques articulaires</span> ; <span class=\"nc-orange_bg\">thrombophilie</span> non majeure : déficit en <span>protéine C / protéine S</span>, <span class=\"nc-orange_bg\">mutation </span><span><span class=\"nc-orange_bg\">Leiden du facteur V</span></span>, mutation <span>G20210A de la prothrombine</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges classiques.</strong> Le <span>tabac</span> et la <span>dyslipidémie</span> ne sont <strong><span class=\"nc-red nc-bold\">pas</span></strong> des <span><span class=\"nc-brown_bg\">facteurs</span> de risque</span> de <span class=\"nc-red_bg\">MTEV</span> (à la différence du risque artériel). Dans <span>50 %</span> des cas <strong>aucun facteur</strong> n'est identifié. Un <span>ATCD familial de <span class=\"nc-red_bg\">MTEV</span></span>, même sans <span class=\"nc-yellow_bg\">thrombophilie </span><span><span class=\"nc-yellow_bg\">héréditaire</span></span> détectée, est considéré comme un marqueur de <span class=\"nc-yellow_bg\">thrombophilie héréditaire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":6},{"id":"226-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la MTEV y compris les formes familiales","contenu":"<div class=\"notion-course\"><p>La constitution du <span>thrombus</span> repose sur la <span>triade de Virchow</span> : <strong><span><span class=\"nc-yellow_bg\">stase veineuse</span></span></strong> + <strong><span>lésion pariétale</span></strong> + <strong><span><span class=\"nc-yellow_bg\">anomalies de l'hémostase</span></span></strong> (hypercoagulabilité). Le point de départ est souvent <strong>distal</strong>, dans les zones de ralentissement du flux (<span class=\"nc-blue_bg\">veines soléaires</span>, <span class=\"nc-blue_bg\">valvules</span>, abouchement des collatérales).</p>\n      <p><strong>Lien <span>TVP</span> → EP.</strong> La plupart des thrombi fibrino-cruoriques proviennent des veines profondes des MI et du pelvis : l'<span>EP est secondaire à une TVP dans 70 %</span> <span class=\"nc-red_bg\">des cas</span>, survenant <span><span class=\"nc-pink nc-bold\">3 à 7 jours</span></span><span class=\"nc-pink nc-bold\"> après</span>. Environ <span>50 %</span> des patients porteurs d'une <span>TVP</span> proximale ont une EP, y compris asymptomatique.</p>\n      <table>\n        <thead><tr><th>Conséquence</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hémodynamique de l'EP</strong></td><td>Obstruction artérielle → ↑ résistances pulmonaires (au-delà de <span>30-50 %</span> d'obstruction) → <span><span class=\"nc-red_bg\">HTAP pré-capillaire</span></span> → ↑ post-charge du VD → <span><span class=\"nc-red nc-bold\">dilatation du VD</span></span> → <span class=\"nc-red nc-bold\">septum paradoxal</span> comprimant le VG → ↓ précharge VG → ↓ débit cardiaque → ↓ PA. L'<span class=\"nc-red_bg\">ischémie du VD</span> aboutit au <span>cœur pulmonaire aigu</span></td></tr>\n          <tr><td><strong><span class=\"nc-yellow_bg\">Hypoxémie</span></strong></td><td>D'abord <span>effet espace mort</span> (alvéoles ventilées non perfusées), puis <span><span class=\"nc-yellow_bg\">effet shunt</span></span> — mécanisme principal — par bronchoconstriction et redistribution du flux ; l'hyperventilation réactionnelle donne une <span><span class=\"nc-red nc-bold\">hypocapnie</span></span> et une <span><span class=\"nc-red nc-bold\">alcalose respiratoire</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes familiales.</strong> Les <span>thrombophilies héréditaires</span> sont retrouvées chez environ 1/4 des patients, mais leur impact clinique est <span class=\"nc-green nc-bold\">faible</span> — sauf le déficit en antithrombine.</p>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">Déficit en antithrombine</span></span> — facteur <span>héréditaire</span> le <strong>plus thrombogène</strong>, même à l'état hétérozygote, mais le plus rare.</li>\n        <li><span>Déficit en protéine C</span> et <span>protéine S</span> — thrombophilies non majeures.</li>\n        <li><span class=\"nc-orange_bg\">Mutation </span><span><span class=\"nc-orange_bg\">Leiden du facteur V</span></span> et mutation <span>G20210A de la prothrombine</span> (hétéro- ou homozygote) — non majeures.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span>Lupus</span> - SAPL</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":3},{"id":"226-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","contenu":"<div class=\"notion-course\"><ul><li>Devant une suspicion, évaluer d’abord la tolérance hémodynamique. En l’absence de choc, estimer la probabilité clinique avec un outil validé et sa version exacte.</li><li>TVP : <span class=\"nc-red nc-bold\">douleur</span>, œdème unilatéral, différence de périmètre, contexte favorisant ; le <span class=\"nc-yellow_bg\">signe de Homans</span> n’est ni fiable ni nécessaire. La phlegmatia caerulea dolens (jambe très douloureuse, cyanosée et tendue) menace le membre et nécessite une prise en charge urgente.</li><li>EP : <span class=\"nc-yellow_bg\">dyspnée</span>, douleur pleurale, <span class=\"nc-yellow_bg\">tachycardie</span>, <span class=\"nc-blue_bg\">hémoptysie</span>, <span class=\"nc-blue_bg nc-bold\">syncope</span> ; aucune n’est <span class=\"nc-yellow_bg\">constante</span>. Une auscultation, une gazométrie, un ECG ou une radiographie normaux ne l’excluent pas.</li><li><b>Scores à ne pas mélanger :</b> Wells TVP à deux niveaux : ≥ 2 probable ; Wells EP original à deux niveaux : &gt; 4 probable, ≤ 4 peu probable. Genève révisé original : 0–3 <span class=\"nc-green nc-bold\">faible</span>, 4–10 <span class=\"nc-green nc-bold\">intermédiaire</span>, ≥ 11 forte ; à deux niveaux, ≥ 6 probable. Les versions simplifiées utilisent d’autres seuils.</li><li>Probabilité non forte : D-dimères dans une stratégie validée ; négatifs, exclusion possible ; positifs, imagerie. Probabilité forte : imagerie directement.</li><li><span class=\"nc-yellow_bg\">TVP</span> : échographie de compression/Doppler ; EP : angioscanner ou scintigraphie selon les contre-indications. Si imagerie négative et forte discordance clinique, poursuivre l’évaluation.</li><li>Diagnostics différentiels : cellulite, rupture de kyste poplité, hématome, lymphœdème pour la jambe ; SCA, pneumopathie, pneumothorax, <span class=\"nc-orange_bg\">insuffisance</span> cardiaque ou dissection pour l’EP. Le délai d’examen dépend de l’urgence : ne <span class=\"nc-blue_bg\">pas</span> attendre 24 heures chez un patient à risque.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/ecg-baston-s1q3.jpg\" alt=\"ECG montrant des signes de cœur pulmonaire aigu au cours d&#x27;une embolie pulmonaire — aspect S1Q3 et tachycardie sinusale\" loading=\"lazy\">\n        <figcaption><span>ECG</span> : signes de cœur pulmonaire aigu — aspect <strong>S1Q3</strong> (onde S en D1, onde Q en D3) et <span>tachycardie</span> sinusale. Ces signes sont inconstants et aspécifiques. Source : fiche source EDN item 226.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":9},{"id":"226-5","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","contenu":"<div class=\"notion-course\"><ul><li>EP à haut risque = instabilité hémodynamique : arrêt cardiaque, choc obstructif ou hypotension persistante (<span class=\"nc-blue_bg\">PAS</span> <span class=\"nc-red nc-bold\">&lt; 90 mmHg</span> ou chute ≥ 40 mmHg pendant plus de 15 minutes), non expliquée par arythmie, hypovolémie ou sepsis.</li><li>Appel réanimation/cardiologie, monitorage, oxygène si nécessaire, accès veineux et soutien hémodynamique adapté. Éviter un remplissage massif qui aggrave la défaillance droite.</li><li>Angioscanner immédiatement si disponible et transport réalisable en sécurité. Sinon ETT au lit pour rechercher surcharge/dysfonction du VD et autres causes de choc. Pas de D-dimères pour décider.</li><li>Si patient trop instable pour le scanner et forte suspicion <span class=\"nc-yellow_bg\">avec</span> arguments échographiques concordants, une reperfusion peut être décidée en urgence par l’équipe. L’ETT ne fournit pas à elle seule une preuve spécifique dans tous les contextes.</li><li>L’absence de surcharge droite fait rechercher une autre cause du choc ; elle n’exclut pas toutes les EP chez un patient stable.</li><li>Traitement : anticoagulation adaptée, généralement HNF dans cette situation, et reperfusion (thrombolyse systémique si indiquée ; embolectomie ou traitement par cathéter si contre-indication/échec selon ressources).</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"226-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","contenu":"<div class=\"notion-course\"><ul><li>Les D-dimères sont un test d’exclusion associé à une probabilité clinique <span class=\"nc-green nc-bold\">faible</span>/<span class=\"nc-green nc-bold\">intermédiaire</span> ou « peu probable », dans une stratégie validée. Un résultat positif ne prouve <span class=\"nc-red nc-bold\">pas</span> une MTEV.</li><li>Pour l’EP, avec méthode exprimée en unités équivalentes fibrinogène (FEU) : seuil habituel 500 µg/L (500 ng/mL) avant 50 ans ; à partir de 50 ans, âge × 10 µg/L. À 70 ans : 700 µg/L. Vérifier méthode et unités, notamment FEU versus DDU.</li><li>Probabilité forte ou instabilité : imagerie directe, sans utiliser des D-dimères négatifs pour exclure.</li><li>Âge, cancer, <span class=\"nc-pink_bg\">grossesse</span>, inflammation ou chirurgie augmentent les <span class=\"nc-brown_bg nc-bold\">faux positifs</span> mais ne rendent pas le test automatiquement interdit. Pendant la <span class=\"nc-pink_bg\">grossesse</span>, employer une stratégie spécifiquement validée.</li><li>Un traitement anticoagulant préalable peut diminuer le taux et compromettre la sensibilité. Ne pas mélanger seuil ajusté à l’âge et algorithme YEARS sans suivre leur protocole respectif.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"226-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","contenu":"<div class=\"notion-course\"><ul><li>L’échographie de compression veineuse est l’examen de première intention d’une TVP ; signe essentiel : veine incompressible. Le Doppler précise thrombus, flux et extension.</li><li>L’examen peut être proximal ou complet ; sa performance est meilleure pour la <span class=\"nc-red_bg\">TVP</span> proximale que distale et dépend des conditions techniques et de l’opérateur. Une veine poplitée appartient au réseau proximal.</li><li>Si échographie proximale négative mais suspicion persistante/D-dimères positifs selon l’algorithme, prévoir une échographie répétée à environ une semaine ou une exploration complète.</li><li>Dans une suspicion d’EP, identifier une TVP proximale suffit généralement à justifier un traitement de MTEV sans imposer une imagerie pulmonaire ; cela ne visualise pas directement une <span class=\"nc-red_bg\">embolie pulmonaire</span>.</li><li>Une échographie veineuse normale n’exclut pas une EP.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/echodoppler-tvp.png\" alt=\"Échodoppler veineux d&#x27;un membre inférieur montrant une thrombose veineuse profonde — veine incompressible avec thrombus endoluminal\" loading=\"lazy\">\n        <figcaption><span>Échodoppler</span> veineux : <span>thrombus</span> endoluminal et veine <strong>incompressible</strong> sous la sonde — signe clé de <span>TVP</span>. Source : fiche source EDN item 226.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/pulmonary-embolism","label":"Radiopaedia : Pulmonary embolism"}]},{"id":"226-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","contenu":"<div class=\"notion-course\"><ul><li>Angioscanner pulmonaire : recherche d’une lacune endovasculaire dans les artères pulmonaires ; évalue aussi le VD et certains diagnostics différentiels. Adapter en cas d’insuffisance rénale, antécédent de réaction au contraste ou grossesse.</li><li>Une imagerie positive doit être interprétée avec la qualité technique et la probabilité clinique, particulièrement pour une anomalie sous-segmentaire isolée. Une imagerie négative discordante avec une <span class=\"nc-green nc-bold\">forte</span> probabilité nécessite une réévaluation.</li><li>Scintigraphie ventilation/perfusion : alternative notamment si le contraste est inapproprié. Une perfusion normale exclut l’EP ; des défauts de perfusion sans défaut ventilatoire correspondant sont évocateurs. Un résultat indéterminé exige des examens complémentaires.</li><li>ETT : recherche du retentissement droit et stratification pronostique ; outil décisif au lit en cas de choc si scanner impossible. Une ETT normale n’exclut pas une EP stable.</li><li>Le <span class=\"nc-red nc-bold\">thrombus</span> est rarement visualisé directement en ETT ; <span class=\"nc-red nc-bold\">dilatation du VD</span>, dysfonction et <span class=\"nc-red nc-bold\">septum paradoxal</span> ne sont pas spécifiques à eux seuls. L’angiographie invasive n’est pas l’examen diagnostique de routine.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/angio-tdm-ep-1.png\" alt=\"Angio-TDM thoracique montrant une embolie pulmonaire — lacune endovasculaire dans une artère pulmonaire\" loading=\"lazy\">\n        <figcaption><span>Angio-<span>TDM</span></span> thoracique : <strong>lacune endovasculaire</strong> (défaut d'opacification) au sein d'une artère pulmonaire — signe direct d'EP. Source : fiche source EDN item 226.</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/angio-tdm-ep-2.png\" alt=\"Angio-TDM thoracique d&#x27;une embolie pulmonaire — autre coupe montrant un thrombus artériel pulmonaire\" loading=\"lazy\">\n        <figcaption><span>Angio-<span>TDM</span></span> thoracique, autre coupe : thrombus obstruant une branche artérielle pulmonaire. Source : fiche source EDN item 226.</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/scintigraphie-vq-mismatch.png\" alt=\"Scintigraphie pulmonaire de ventilation-perfusion montrant un mismatch — défect de perfusion sans défect de ventilation\" loading=\"lazy\">\n        <figcaption><span>Scintigraphie</span> de ventilation-perfusion : <strong>mismatch</strong> — défect de perfusion segmentaire sans défect ventilatoire en regard (haute probabilité PIOPED). Source : fiche source EDN item 226.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":8},{"id":"226-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","contenu":"<div class=\"notion-course\"><ul><li>Commencer par l’hémodynamique : une instabilité définit le haut risque et appelle la stratégie de reperfusion.</li><li>Chez le patient stable, sPESI : un point pour <span class=\"nc-blue_bg\">âge</span> &gt; 80 ans, <span class=\"nc-orange_bg\">cancer</span>, maladie cardiaque ou respiratoire chronique, FC ≥ 110/min, <span class=\"nc-blue_bg\">PAS</span> &lt; 100 mmHg, SpO₂ &lt; 90 %. Ce score est pronostique, <span class=\"nc-blue_bg\">pas</span> diagnostique.</li><li>Associer l’évaluation du VD par ETT ou scanner et la troponine. Une atteinte du VD et une troponine positive chez un patient de risque clinique accru définissent le risque <span class=\"nc-green nc-bold\">intermédiaire</span> élevé : surveillance hospitalière rapprochée, sans thrombolyse systématique en l’absence de dégradation.</li><li>Faible risque : outils validés (sPESI/PESI ou Hestia), absence d’élément défavorable, risque hémorragique acceptable et traitement réalisable. L’ambulatoire exige compréhension, soutien, accès au traitement et suivi rapide.</li><li>Un score rassurant n’annule pas une hypoxémie, une douleur incontrôlée, une dysfonction droite ou une difficulté sociale. Hestia est une liste d’exclusion de l’ambulatoire, à appliquer dans sa version complète.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":3},{"id":"226-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">TVP</span> <span class=\"nc-yellow_bg nc-bold\">proximale</span>/EP confirmée : <span class=\"nc-pink_bg\">anticoagulation</span> curative, sauf contre-indication majeure. Si probabilité élevée et imagerie retardée, discuter une <span class=\"nc-pink_bg\">anticoagulation</span> d’attente en tenant compte du risque hémorragique.</li><li>Chez l’adulte éligible, un <span class=\"nc-pink_bg\">AOD</span> est souvent préféré. <span class=\"nc-pink nc-bold\">Apixaban</span> et <span class=\"nc-pink nc-bold\">rivaroxaban</span> ont une phase initiale orale renforcée ; <span class=\"nc-red nc-bold\">dabigatran</span>/édoxaban nécessitent une phase parentérale préalable selon leur AMM et disponibilité. Ne pas appliquer la dose d’entretien dès le premier jour.</li><li>HBPM/fondaparinux ou <span class=\"nc-pink_bg\">HNF</span> selon <span class=\"nc-pink_bg\">grossesse</span>, fonction rénale, risque et contexte ; <span class=\"nc-pink_bg\">HNF</span> notamment si instabilité ou besoin de réversibilité rapide. <span class=\"nc-red nc-bold\">AVK</span> si indication spécifique, avec chevauchement parentéral ≥ 5 jours et INR thérapeutique <span class=\"nc-yellow_bg\">confirmé</span>.</li><li>Situations nécessitant un choix particulier : grossesse, allaitement, <span class=\"nc-orange_bg\">insuffisance</span> rénale sévère, SAPL à haut risque, cancer avec risque de saignement/interactions. La posologie dépend de la molécule, du poids, de l’<span class=\"nc-blue_bg\">âge</span> et de la fonction rénale calculée selon son référentiel.</li><li>Bilan initial : <span class=\"nc-blue_bg\">NFS-plaquettes</span>, fonction rénale et hépatique, hémostase et recherche de grossesse selon contexte. Les AOD ne nécessitent pas d’INR, mais exigent un suivi clinique et biologique périodique.</li><li><span class=\"nc-green_bg\">Lever précoce</span> lorsque l’état le permet, prise en charge de la douleur, compression symptomatique adaptée après bilan artériel, éducation et carte d’anticoagulé. Pas de délai universel obligatoire d’une heure après la première dose.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":6},{"id":"226-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","contenu":"<div class=\"notion-course\"><ul><li>La compression peut réduire douleur et œdème après <span class=\"nc-red_bg\">TVP</span> ; choisir dispositif, pression et durée en fonction des symptômes, de la tolérance et de la perfusion artérielle.</li><li>Les recommandations sur la prévention systématique du syndrome post-thrombotique diffèrent. Ne pas promettre une réduction de 50 % chez tous ni imposer deux ans à tout patient asymptomatique ; réévaluer régulièrement.</li><li>En classification française, classe III : 20,1–36 mmHg à la cheville ; ne pas confondre les classes nationales avec une prescription exprimée directement en mmHg.</li><li>Artériopathie sévère (notamment IPS &lt; 0,6), ischémie critique ou pression distale très basse : pas de compression forte standard. Entre 0,6 et 0,9, avis et adaptation ; IPS incompressible : mesurer la pression d’orteil.</li><li>Phlegmatia, thrombose septique, décompensation cardiaque ou atteinte cutanée aiguë grave : prise en charge spécialisée avant d’appliquer une compression habituelle.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Compression médicale dans les affections veineuses chroniques</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"226-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","contenu":"<div class=\"notion-course\"><ul><li>La contraception combinée œstroprogestative augmente le risque de <span class=\"nc-red_bg\">MTEV</span> et est généralement contre-indiquée en cas d’antécédent personnel ou de thrombophilie connue. Les antécédents familiaux précoces imposent une évaluation individualisée.</li><li>Après une MTEV sous œstroprogestatif, organiser un relais vers une méthode adaptée ; ne <span class=\"nc-red nc-bold\">pas</span> donner comme règle universelle de finir tranquillement la plaquette sans évaluation. L’arrêt et le relais sous anticoagulation tiennent aussi compte du risque de grossesse et de saignement.</li><li>Options selon le contexte : microprogestatif, implant progestatif, DIU au lévonorgestrel, DIU cuivre. Les molécules et dispositifs ne contiennent pas tous de la « progestérone » ; le DIU cuivre peut majorer les saignements sous anticoagulant.</li><li>Une contraception efficace est nécessaire pendant les traitements incompatibles avec la grossesse. Anticiper tout projet de grossesse avec l’équipe ; ne pas arrêter seule l’<span class=\"nc-pink_bg\">anticoagulation</span>.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"226-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les situations nécessitant une prévention de la MTEV","contenu":"<div class=\"notion-course\"><ul><li>Évaluer à chaque hospitalisation les risques thrombotique et hémorragique, la mobilité, les antécédents, le <span class=\"nc-orange nc-bold\">cancer</span>, la chirurgie et les contre-indications ; réévaluer lors d’un changement clinique.</li><li>Prévention médicamenteuse si bénéfice attendu (<span class=\"nc-pink_bg\">HBPM</span> ou autre stratégie adaptée au contexte et au rein). L’âge de 40 ans ou une durée de trois jours ne suffisent pas seuls à décider.</li><li>En chirurgie, le type de geste et le risque individuel déterminent molécule, début et durée ; certaines chirurgies orthopédiques ou carcinologiques justifient une prolongation après la sortie.</li><li>Mobilisation précoce. Si prophylaxie pharmacologique contre-indiquée, compression pneumatique intermittente selon situation et protocole ; les bas ne remplacent pas universellement une prophylaxie indiquée.</li><li>Voyage prolongé : bouger régulièrement et mobiliser les mollets ; compression et éventuellement prophylaxie médicamenteuse seulement chez des patients sélectionnés à haut risque, après avis. Pas d’anticoagulant ou d’aspirine pour tous les voyageurs.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"226-14","rang":"B","rubrique":"Prise en charge","titre":"Savoir déterminer la durée du traitement anticoagulant (TVP proximale et EP)","contenu":"<div class=\"notion-course\"><ul><li>TVP proximale ou EP : au moins trois mois de traitement dans la majorité des cas, puis décision explicite de poursuite ou d’arrêt.</li><li>Premier événement provoqué par un facteur <span class=\"nc-green_bg\">transitoire majeur</span> disparu : trois mois suffisent souvent. Ne pas prolonger uniquement parce que le scanner initial montrait de nombreux caillots.</li><li>Événement non provoqué, récidive ou facteur persistant : discuter un traitement prolongé, voire sans date de fin prédéfinie, selon risque de récidive et de saignement, préférences et tolérance.</li><li><span class=\"nc-red_bg\">Cancer actif</span> : traitement au moins plusieurs mois et réévaluation tant que le <span class=\"nc-orange nc-bold\">cancer</span> ou son traitement reste actif. <span class=\"nc-red_bg\">SAPL</span> à haut risque : stratégie spécifique, souvent <span class=\"nc-pink_bg\">AVK</span>.</li><li>Une prolongation n’est pas une décision définitive sans suivi : réévaluer au moins annuellement et lors de toute modification du terrain. Les doses réduites de certains <span class=\"nc-pink_bg\">AOD</span> en phase <span class=\"nc-orange nc-bold\">prolongée</span> ont des indications précises.</li><li>La durée d’une TVP distale ou d’une TVS suit une stratégie distincte ; ne pas transposer automatiquement les règles de l’EP.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"226-15","rang":"B","rubrique":"Étiologies","titre":"Savoir porter l’indication d’une recherche de cancer en cas de MTEV (TVP, EP)","contenu":"<div class=\"notion-course\"><ul><li>Une MTEV non provoquée peut révéler un <span class=\"nc-orange_bg\">cancer</span>. Rechercher signes fonctionnels, amaigrissement, examen anormal et anomalies biologiques ; revoir antécédents et dépistages recommandés pour l’âge et le sexe.</li><li>Bilan initial limité : interrogatoire/examen complets et biologie de base, puis examens ciblés selon les anomalies. Ne pas attendre un <span class=\"nc-red nc-bold\">bilan de thrombophilie négatif</span> pour rechercher un symptôme évocateur.</li><li>Pas de scanner corps entier, TEP, marqueurs tumoraux, <span class=\"nc-pink nc-bold\">PSA</span>, <span class=\"nc-pink nc-bold\">échographie pelvienne</span> ou endoscopie systématiques uniquement du fait de la MTEV en l’absence d’orientation.</li><li>Informer sur les symptômes nouveaux et assurer le suivi. Le risque de <span class=\"nc-orange nc-bold\">cancer</span> varie selon la population ; une large fourchette historique de 6 à 28 % ne s’applique <span class=\"nc-red nc-bold\">pas</span> à chaque première MTEV.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"226-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Savoir évoquer les complications à long terme de la MTEV (syndrome post-thrombotique, HTAP)","contenu":"<div class=\"notion-course\"><p>Deux complications tardives sont à connaître, l'une veineuse après <span>TVP</span>, l'autre artérielle pulmonaire après EP.</p>\n      <table>\n        <thead><tr><th></th><th>Syndrome post-<span>thrombotique</span></th><th>HTP post-<span>embolique</span></th></tr></thead>\n        <tbody>\n          <tr><td>Suit</td><td>Une <span>TVP</span></td><td>Une <span>EP</span></td></tr>\n          <tr><td>Fréquence</td><td><span>20-50 %</span> développent une IVC à<span> <span class=\"nc-pink_bg\">5-10 ans</span></span> ; <span>5-10 %</span> une forme sévère — risque majeur si <span class=\"nc-red nc-bold\">thrombose ilio-fémorale</span></td><td>Rare (<span>2-3 %</span>) mais grave</td></tr>\n          <tr><td>Mécanisme</td><td>Obstruction veineuse résiduelle et/ou <span><span class=\"nc-red nc-bold\">destruction valvulaire</span></span> → reflux profond → insuffisance veineuse chronique</td><td>Persistance d'une obstruction significative du lit artériel pulmonaire</td></tr>\n          <tr><td>Clinique</td><td><span>Lourdeur de jambe</span>, <span>œdème</span>, troubles trophiques, ulcères ; sévérité évaluée par le <span>score de <span class=\"nc-yellow nc-bold\">Villalta</span></span></td><td><span><span class=\"nc-yellow_bg\">Dyspnée persistante</span></span><span class=\"nc-yellow_bg\"> à distance d'une EP</span> (<span class=\"nc-yellow_bg\">&gt;</span><span><span class=\"nc-yellow_bg\"> 3 mois</span></span> après le traitement)</td></tr>\n          <tr><td>Prévention</td><td><span class=\"nc-pink_bg\">Anticoagulation efficace</span> + <span>compression élastique</span> dès la phase initiale</td><td><span>Dépistage</span> devant toute <span>dyspnée</span> persistante post-EP (voir objectif suivant)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 227 — Insuffisance veineuse chronique - varices</em></p><h4>Points de raisonnement et précautions</h4><ul><li>Le syndrome post-thrombotique peut apparaître dès les premiers mois, et non uniquement à cinq ou dix ans. L’HTP thromboembolique chronique relève d’un centre expert ; le traitement peut associer endartériectomie, angioplastie pulmonaire et traitement médical selon l’opérabilité.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"226-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître la complication à dépister avant d’arrêter un traitement anticoagulant pour EP","contenu":"<div class=\"notion-course\"><p>La complication à dépister avant d'arrêter une <span>anticoagulation</span> prescrite pour EP est l'<span><span class=\"nc-red_bg\">hypertension pulmonaire post-embolique</span> (HTP-PE)</span> — rare (<span>2-3 %</span>) mais grave, liée à la persistance d'une obstruction significative du lit artériel pulmonaire.</p>\n      <p><strong>Signe d'appel :</strong> une <span>dyspnée persistante</span> à distance de l'EP, <span class=\"nc-yellow_bg\">&gt; </span><span><span class=\"nc-yellow_bg\">3 mois</span></span> après le traitement.</p>\n      <p><strong>Démarche diagnostique :</strong></p>\n      <ol>\n        <li><span>ETT</span> : estimation de la PAP systolique et recherche de signes indirects (dilatation et dysfonction du VD).</li>\n        <li>Si <span><span class=\"nc-red nc-bold\">PAPs élevée</span></span> ou risque échographique d'HTAP intermédiaire/élevé → <span>scintigraphie de ventilation-perfusion</span>.</li>\n        <li>Si <span><span class=\"nc-red nc-bold\">défects perfusionnels</span></span><span class=\"nc-red nc-bold\"> à la </span><span><span class=\"nc-red nc-bold\">scintigraphie</span></span> → confirmation par <span><span class=\"nc-blue_bg\">cathétérisme cardiaque droit</span></span>.</li>\n      </ol>\n      <div class=\"callout callout-info\"><strong>Prise en charge.</strong> Le traitement de référence de l'HTP post-<span>embolique</span> est l'<span><span class=\"nc-pink nc-bold\">endartériectomie pulmonaire</span></span>.</div><h4>Points de raisonnement et précautions</h4><ul><li>Réévaluer les symptômes à trois–six mois après l’EP. Une dyspnée persistante doit déclencher une exploration, même si l’échographie est peu contributive. Pas d’angioscanner de contrôle systématique chez tout patient asymptomatique ; ne pas arrêter l’anticoagulation sans décision explicite sur récidive et saignement.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418120bbd9dda871b9e9a6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Embolie pulmonaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"226-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge une thrombose veineuse superficielle","contenu":"<div class=\"notion-course\"><ul><li>TVS : cordon superficiel rouge, induré et douloureux. Réaliser un écho-Doppler pour mesurer l’extension, la distance à la jonction profonde et rechercher une TVP associée ; elle n’est pas toujours bénigne.</li><li>TVP associée ou TVS très proche du réseau <span class=\"nc-yellow_bg\">profond</span> (repère ≤ 3 cm de la jonction) : évaluation pour anticoagulation à dose curative selon protocole spécialisé.</li><li>TVS d’au moins 5 cm, à distance de la jonction profonde : <span class=\"nc-pink_bg\">fondaparinux</span> 2,5 mg/j pendant <span class=\"nc-pink nc-bold\">45 jours</span> classiquement, si fonction rénale et risque hémorragique compatibles ; alternatives selon recommandations.</li><li>TVS courte à faible risque : traitement symptomatique et surveillance ; anticoagulation discutée si <span class=\"nc-brown_bg\">facteurs</span> de risque ou progression. Éviter les AINS systémiques associés sans réflexion à une anticoagulation.</li><li>Une TVS spontanée sur veine non variqueuse ou récidivante justifie une recherche orientée de cause ; pas de batterie d’examens systématique sans contexte.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · MTEV (226)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3ada3f65a37fbf437?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Thrombose veineuse profonde</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 226</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Raisonner avant le chiffre","contenu":"<div class=\"notion-course\"><p>Interpréter un seuil avec le tableau clinique, le référentiel et les unités ; une complication aiguë impose de réévaluer immédiatement la stratégie.</p></div>"},{"type":"piege","titre":"Source et synthèse","contenu":"<div class=\"notion-course\"><p>Les schémas du collège restent accessibles. Les arbres ATLAS et leurs compléments sont explicitement identifiés et reliés aux objectifs concernés.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Rechercher les signes de gravité puis préciser la probabilité et le mécanisme.</li><li>Choisir les examens capables de modifier la décision et confronter les résultats à la clinique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Adapter la prise en charge à l’urgence, au terrain, aux contre-indications et aux préférences.</li><li>Prévoir surveillance, éducation et réévaluation ; utiliser les arbres reliés au cours.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire/","label":"CNEC · Item 226 ↗"},{"href":"https://www.has-sante.fr/jcms/c_1009308/fr/compression-medicale-dans-les-affections-veineuses-chroniques-fiche-buts","label":"HAS · Compression médicale dans les affections veineuses chroniques ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Quelle situation ?","detail":"<ul><li>Localisation et contexte conditionnent la stratégie.</li></ul>","branches":[{"label":"TVS","to":"tvs"},{"label":"TVP proximale / EP","to":"anticoag"},{"label":"Prévention sans événement","to":"prevention"}]},{"id":"tvs","kind":"decision","label":"Extension ≥ 5 cm ou proximité du profond ?","detail":"<ul><li>Doppler et distance à la jonction ; TVP associée ?</li></ul>","branches":[{"label":"Proximité / TVP","to":"curatif"},{"label":"Étendue à distance","to":"45jours"},{"label":"Courte à faible risque","to":"symptomes"}]},{"id":"curatif","kind":"finish","label":"Stratégie curative spécialisée","detail":"<ul><li>Évaluer dose et durée selon extension et risque.</li></ul>","branches":[]},{"id":"45jours","kind":"finish","label":"Fondaparinux préventif 45 jours si éligible","detail":"<ul><li>Fonction rénale, risque hémorragique et alternatives.</li></ul>","branches":[]},{"id":"symptomes","kind":"finish","label":"Traitement symptomatique et surveillance","detail":"<ul><li>Réévaluer une progression ou un contexte inhabituel.</li></ul>","branches":[]},{"id":"prevention","kind":"finish","label":"Balance thrombose–saignement et mobilité","detail":"<ul><li>Hospitalisation, chirurgie ou voyage ; pas de prophylaxie universelle.</li></ul>","branches":[]},{"id":"anticoag","kind":"decision","label":"Choisir anticoagulant et mesures associées","detail":"<ul><li>Terrain, rein, grossesse/SAPL/cancer ; éducation et contraception.</li></ul>","branches":[{"label":"Après au moins trois mois","to":"duree"}]},{"id":"duree","kind":"decision","label":"Facteur majeur transitoire disparu ?","detail":"<ul><li>Rechercher récidive, facteur persistant et signes de cancer.</li></ul>","branches":[{"label":"Oui","to":"court"},{"label":"Non / récidive","to":"prolonger"}]},{"id":"court","kind":"decision","label":"Arrêt envisageable après réévaluation","detail":"<ul><li>Décision partagée ; vérifier symptômes et indication résiduelle.</li></ul>","branches":[{"label":"Suivi","to":"suivi"}]},{"id":"prolonger","kind":"decision","label":"Discuter traitement prolongé","detail":"<ul><li>Récidive versus hémorragie ; réévaluation régulière.</li></ul>","branches":[{"label":"Suivi","to":"suivi"}]},{"id":"suivi","kind":"decision","label":"Dyspnée persistante ou séquelles de jambe ?","detail":"<ul><li>À trois–six mois et ensuite selon symptômes.</li></ul>","branches":[{"label":"Dyspnée","to":"htp"},{"label":"Jambe","to":"spt"},{"label":"Aucun symptôme","to":"education"}]},{"id":"htp","kind":"finish","label":"Explorer une HTP thromboembolique chronique","detail":"<ul><li>ETT, scintigraphie et centre expert selon résultats.</li></ul>","branches":[]},{"id":"spt","kind":"finish","label":"Évaluer syndrome post-thrombotique","detail":"<ul><li>Clinique, Villalta et Doppler ; compression adaptée aux symptômes.</li></ul>","branches":[]},{"id":"education","kind":"finish","label":"Suivi et consignes de récidive / saignement","detail":"<ul><li>Pas d’imagerie de contrôle systématique chez tout patient asymptomatique.</li></ul>","branches":[]}]},"cards":[{"i":"59edd416dcdd","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Quelle est la définition d'une embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-red_bg\">embolie pulmonaire</span> (EP) est l'<strong>obstruction des artères pulmonaires</strong> ou de leurs branches par un ou des <span class=\"nc-red nc-bold\">thrombus</span>.</p></div>"},{"i":"96896aea4321","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Quelle est la définition d'une thrombose veineuse profonde (TVP) ?","a":"<div class=\"notion-course\"><p>Une thrombose veineuse profonde (TVP) est l'<strong>obstruction thrombotique d'un tronc veineux <span class=\"nc-yellow_bg\">profond</span></strong>, localisée le plus souvent aux membres inférieurs.</p></div>"},{"i":"b14c7e411639","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Comment définit-on une TVP distale ?","a":"<div class=\"notion-course\"><p>Une TVP distale est une <strong>thrombose sous-poplitée</strong>, affectant les veines jambières (<span class=\"nc-pink_bg\">tibiale antérieure</span> et postérieure, <span class=\"nc-pink_bg\">fibulaire</span>) et surales (<span class=\"nc-pink_bg\">soléaire</span>, <span class=\"nc-pink_bg\">gastrocnémienne</span>).</p></div>"},{"i":"eaaaad52e2d7","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Comment définit-on une TVP proximale ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-yellow_bg\">TVP</span> <span class=\"nc-yellow_bg nc-bold\">proximale</span> est une <strong>thrombose sus-poplitée</strong>, c'est-à-dire qu'elle affecte les veines poplitée, fémorale, iliaque ou cave. Elle est associée à un risque élevé d'<span class=\"nc-red_bg\">embolie pulmonaire</span>.</p></div>"},{"i":"ed9975e26f08","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Qu'est-ce qu'une embolie pulmonaire à haut risque ?","a":"<div class=\"notion-course\"><ul><li>EP à haut risque = instabilité hémodynamique : arrêt cardiaque, choc obstructif ou hypotension persistante (<span class=\"nc-blue_bg\">PAS</span> <span class=\"nc-red nc-bold\">&lt; 90 mmHg</span> ou chute ≥ 40 mmHg pendant plus de 15 minutes), non expliquée par arythmie, hypovolémie ou sepsis.</li></ul></div>"},{"i":"0e077bba12e6","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quel bilan pré-thérapeutique est nécessaire avant d'initier un traitement anticoagulant pour une TVP/EP non grave ?","a":"<div class=\"notion-course\"><ul><li>Bilan initial : <span class=\"nc-blue_bg\">NFS-plaquettes</span>, fonction rénale et hépatique, hémostase et recherche de grossesse selon contexte. Les AOD ne nécessitent pas d’INR, mais exigent un suivi clinique et biologique périodique.</li></ul></div>"},{"i":"5e4a171a0fb1","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quels sont les anticoagulants de première intention à privilégier pour le traitement initial d'une TVP/EP non grave, et quelles sont leurs caractéristiques principales ?","a":"<div class=\"notion-course\"><ul><li>Chez l’adulte éligible, un <span class=\"nc-pink_bg\">AOD</span> est souvent préféré. <span class=\"nc-pink nc-bold\">Apixaban</span> et <span class=\"nc-pink nc-bold\">rivaroxaban</span> ont une phase initiale orale renforcée ; <span class=\"nc-red nc-bold\">dabigatran</span>/édoxaban nécessitent une phase parentérale préalable selon leur AMM et disponibilité. Ne pas appliquer la dose d’entretien dès le premier jour.</li><li>Situations nécessitant un choix particulier : grossesse, allaitement, <span class=\"nc-orange_bg\">insuffisance</span> rénale sévère, SAPL à haut risque, cancer avec risque de saignement/interactions. La posologie dépend de la molécule, du poids, de l’<span class=\"nc-blue_bg\">âge</span> et de la fonction rénale calculée selon son référentiel.</li><li>Bilan initial : <span class=\"nc-blue_bg\">NFS-plaquettes</span>, fonction rénale et hépatique, hémostase et recherche de grossesse selon contexte. Les AOD ne nécessitent pas d’INR, mais exigent un suivi clinique et biologique périodique.</li></ul></div>"},{"i":"82f50d23b6c3","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quelle est l'approche thérapeutique initiale recommandée en cas de suspicion forte ou intermédiaire de TVP/EP (non grave), avant même la confirmation diagnostique, en l'absence de risque hémorragique élevé ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">TVP</span> <span class=\"nc-yellow_bg nc-bold\">proximale</span>/EP confirmée : <span class=\"nc-pink_bg\">anticoagulation</span> curative, sauf contre-indication majeure. Si probabilité élevée et imagerie retardée, discuter une <span class=\"nc-pink_bg\">anticoagulation</span> d’attente en tenant compte du risque hémorragique.</li></ul></div>"},{"i":"bfa71468af57","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"En cas de traitement par héparine suivi d'un relai par AVK pour une TVP/EP non grave, quelles sont les modalités de ce relai et les critères d'arrêt de l'héparine ?","a":"<div class=\"notion-course\"><ul><li>HBPM/fondaparinux ou <span class=\"nc-pink_bg\">HNF</span> selon <span class=\"nc-pink_bg\">grossesse</span>, fonction rénale, risque et contexte ; <span class=\"nc-pink_bg\">HNF</span> notamment si instabilité ou besoin de réversibilité rapide. <span class=\"nc-red nc-bold\">AVK</span> si indication spécifique, avec chevauchement parentéral ≥ 5 jours et INR thérapeutique <span class=\"nc-yellow_bg\">confirmé</span>.</li></ul></div>"},{"i":"dbce8942a2ba","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quelles sont les contre-indications majeures à l'instauration d'un traitement anticoagulant pour une TVP/EP ?","a":"<div class=\"notion-course\"><ul><li>Une <span class=\"nc-orange_bg\">hémorragie active</span> majeure non contrôlée ou certaines situations intracrâniennes imposent une décision urgente spécialisée.</li><li>Thrombopénie, coagulopathie, insuffisance rénale et geste récent nécessitent une balance individualisée ; un seuil biologique isolé n’est pas une règle universelle pour tous les patients.</li><li>Si une anticoagulation indispensable est impossible, discuter les alternatives temporaires dans l’équipe spécialisée.</li></ul></div>"},{"i":"e43a221a810b","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quelles sont les mesures associées au traitement anticoagulant d'une TVP/EP non grave ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-green_bg\">Lever précoce</span> lorsque l’état le permet, prise en charge de la douleur, compression symptomatique adaptée après bilan artériel, éducation et carte d’anticoagulé. Pas de délai universel obligatoire d’une heure après la première dose.</li></ul></div>"},{"i":"13208797f9e3","n":226,"o":"226-11","u":"Prise en charge","t":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","q":"Quelle est l'indication principale de la compression élastique dans le contexte d'une TVP des membres inférieurs ?","a":"<div class=\"notion-course\"><ul><li>La compression peut réduire douleur et œdème après <span class=\"nc-red_bg\">TVP</span> ; choisir dispositif, pression et durée en fonction des symptômes, de la tolérance et de la perfusion artérielle.</li><li>Les recommandations sur la prévention systématique du syndrome post-thrombotique diffèrent. Ne pas promettre une réduction de 50 % chez tous ni imposer deux ans à tout patient asymptomatique ; réévaluer régulièrement.</li></ul></div>"},{"i":"55533ddf2a83","n":226,"o":"226-11","u":"Prise en charge","t":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","q":"Quelles sont les modalités pratiques de la compression élastique pour une TVP des membres inférieurs ?","a":"<div class=\"notion-course\"><ul><li>La compression peut réduire douleur et œdème après <span class=\"nc-red_bg\">TVP</span> ; choisir dispositif, pression et durée en fonction des symptômes, de la tolérance et de la perfusion artérielle.</li><li>En classification française, classe III : 20,1–36 mmHg à la cheville ; ne pas confondre les classes nationales avec une prescription exprimée directement en mmHg.</li></ul></div>"},{"i":"7508afa5336c","n":226,"o":"226-11","u":"Prise en charge","t":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","q":"Quelles sont les contre-indications spécifiques à la compression élastique dans la prise en charge d'une TVP des membres inférieurs ?","a":"<div class=\"notion-course\"><ul><li>Artériopathie sévère (notamment IPS &lt; 0,6), ischémie critique ou pression distale très basse : pas de compression forte standard. Entre 0,6 et 0,9, avis et adaptation ; IPS incompressible : mesurer la pression d’orteil.</li><li>Phlegmatia, thrombose septique, décompensation cardiaque ou atteinte cutanée aiguë grave : prise en charge spécialisée avant d’appliquer une compression habituelle.</li></ul></div>"},{"i":"52a4200b66e4","n":226,"o":"226-12","u":"Prise en charge","t":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","q":"Quelle est la conduite à tenir en cas de MTEV survenant chez une patiente sous contraception œstro-progestative (COP) ?","a":"<div class=\"notion-course\"><ul><li>Après une MTEV sous œstroprogestatif, organiser un relais vers une méthode adaptée ; ne <span class=\"nc-red nc-bold\">pas</span> donner comme règle universelle de finir tranquillement la plaquette sans évaluation. L’arrêt et le relais sous anticoagulation tiennent aussi compte du risque de grossesse et de saignement.</li><li>Une contraception efficace est nécessaire pendant les traitements incompatibles avec la grossesse. Anticiper tout projet de grossesse avec l’équipe ; ne pas arrêter seule l’<span class=\"nc-pink_bg\">anticoagulation</span>.</li></ul></div>"},{"i":"7215d7297a47","n":226,"o":"226-12","u":"Prise en charge","t":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","q":"Quelles sont les alternatives contraceptives non thrombogènes qui peuvent être proposées chez une patiente avec un risque ou un antécédent de MTEV ?","a":"<div class=\"notion-course\"><ul><li>Options selon le contexte : microprogestatif, implant progestatif, DIU au lévonorgestrel, DIU cuivre. Les molécules et dispositifs ne contiennent pas tous de la « progestérone » ; le DIU cuivre peut majorer les saignements sous anticoagulant.</li></ul></div>"},{"i":"c208bc3c9f90","n":226,"o":"226-12","u":"Prise en charge","t":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","q":"Quelles sont les situations où une contraception œstro-progestative (COP) est contre-indiquée chez une patiente ayant un antécédent ou un risque de maladie thrombo-embolique veineuse (MTEV) ?","a":"<div class=\"notion-course\"><ul><li>La contraception combinée œstroprogestative augmente le risque de <span class=\"nc-red_bg\">MTEV</span> et est généralement contre-indiquée en cas d’antécédent personnel ou de thrombophilie connue. Les antécédents familiaux précoces imposent une évaluation individualisée.</li></ul></div>"},{"i":"0833c4083960","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les recommandations de prévention de la MTEV lors d'un voyage prolongé (> 6 heures) ?","a":"<div class=\"notion-course\"><ul><li>Voyage prolongé : bouger régulièrement et mobiliser les mollets ; compression et éventuellement prophylaxie médicamenteuse seulement chez des patients sélectionnés à haut risque, après avis. Pas d’anticoagulant ou d’aspirine pour tous les voyageurs.</li></ul></div>"},{"i":"20d6d7c98970","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les indications de l'anticoagulation préventive de la MTEV chez les patients hospitalisés en milieu médical ?","a":"<div class=\"notion-course\"><ul><li>Évaluer à chaque hospitalisation les risques thrombotique et hémorragique, la mobilité, les antécédents, le <span class=\"nc-orange nc-bold\">cancer</span>, la chirurgie et les contre-indications ; réévaluer lors d’un changement clinique.</li><li>Prévention médicamenteuse si bénéfice attendu (<span class=\"nc-pink_bg\">HBPM</span> ou autre stratégie adaptée au contexte et au rein). L’âge de 40 ans ou une durée de trois jours ne suffisent pas seuls à décider.</li></ul></div>"},{"i":"7b36d568eb9c","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les mesures non médicamenteuses de prévention de la maladie thrombo-embolique veineuse (MTEV) ?","a":"<div class=\"notion-course\"><ul><li>Mobilisation précoce. Si prophylaxie pharmacologique contre-indiquée, compression pneumatique intermittente selon situation et protocole ; les bas ne remplacent pas universellement une prophylaxie indiquée.</li></ul></div>"},{"i":"e2ba60c08276","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les indications de l'anticoagulation préventive de la MTEV dans le contexte post-opératoire ?","a":"<div class=\"notion-course\"><ul><li>En chirurgie, le type de geste et le risque individuel déterminent molécule, début et durée ; certaines chirurgies orthopédiques ou carcinologiques justifient une prolongation après la sortie.</li></ul></div>"},{"i":"2e2ec98d9a3e","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants persistants majeurs de la maladie thromboembolique veineuse (MTEV) ?","a":"<div class=\"notion-course\">Les facteurs favorisants persistants majeurs de la MTEV sont :\n<ul>\n<li><strong><span class=\"nc-red_bg\">Cancer actif</span></strong>.</li>\n<li><strong>Thrombophilie majeure</strong>, notamment le <strong><span class=\"nc-red_bg\">déficit en antithrombine</span></strong> et le <strong>Syndrome des Anticorps Anti-<span class=\"nc-green_bg\">Phospholipides</span> (<span class=\"nc-red_bg\">SAPL</span>)</strong>, qui est la seule <span class=\"nc-yellow_bg\">thrombophilie acquise</span>.</li>\n</ul></div>"},{"i":"564f3cf148bc","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les pièges à éviter concernant les facteurs de risque de la maladie thromboembolique veineuse (MTEV) ?","a":"<div class=\"notion-course\">Il est important de retenir que :\n<ul>\n<li>Les <span class=\"nc-brown_bg\">facteurs</span> artériels ne se transposent pas directement à la MTEV. Un antécédent familial augmente la suspicion de prédisposition, mais ne prouve pas une thrombophilie biologique héréditaire.</li>\n<li>Dans environ <strong>50 % des cas</strong>, aucun facteur favorisant n'est identifié.</li>\n<li>Les <span class=\"nc-brown_bg\">facteurs</span> artériels ne se transposent pas directement à la MTEV. Un antécédent familial augmente la suspicion de prédisposition, mais ne prouve pas une thrombophilie biologique héréditaire.</li>\n</ul></div>"},{"i":"7972cfd5ccb6","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants persistants mineurs de la maladie thromboembolique veineuse (MTEV) ?","a":"<div class=\"notion-course\">Les facteurs favorisants persistants mineurs de la MTEV comprennent :\n<ul>\n<li><strong>Âge supérieur à 65 ans</strong>.</li>\n<li><strong>Obésité</strong>.</li>\n<li><strong><span class=\"nc-blue_bg\">Syndrome néphrotique</span></strong>.</li>\n<li><strong><span class=\"nc-blue_bg\">Hémoglobinurie Paroxystique Nocturne</span> (HPN)</strong>.</li>\n<li><strong>Maladies Inflammatoires Chroniques Intestinales (<span class=\"nc-blue_bg\">MICI</span>)</strong>.</li>\n<li><strong><span class=\"nc-blue_bg\">Maladies inflammatoires chroniques articulaires</span></strong>.</li>\n<li><strong>Thrombophilie non majeure</strong>, telle que le <strong>déficit en protéine C ou protéine S</strong>, la <strong><span class=\"nc-orange_bg\">mutation Leiden du facteur V</span></strong>, ou la <strong>mutation G20210A de la prothrombine</strong>.</li>\n</ul></div>"},{"i":"cd7972587f1e","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants temporaires majeurs de la maladie thromboembolique veineuse (MTEV) ?","a":"<div class=\"notion-course\">Les facteurs favorisants temporaires majeurs de la MTEV incluent :\n<ul>\n<li><strong>Chirurgie sous anesthésie générale</strong> de moins de 3 mois.</li>\n<li><strong><span class=\"nc-orange_bg\">Fracture d'un membre inférieur</span></strong> de moins de 3 mois.</li>\n<li><strong>Immobilisation</strong> de plus de 3 jours pour motif médical aigu de moins de 3 mois.</li>\n<li>Œstrogènes, <span class=\"nc-pink_bg\">grossesse</span> et <span class=\"nc-pink_bg\">post-partum</span> sont des <span class=\"nc-brown_bg\">facteurs</span> transitoires de MTEV ; leur classification en facteur majeur ou mineur dépend du référentiel et du contexte, et ne doit <span class=\"nc-red nc-bold\">pas</span> être confondue avec celle d’une chirurgie majeure.</li>\n</ul></div>"},{"i":"fe37a44d01f5","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants temporaires mineurs de la maladie thromboembolique veineuse (MTEV) ?","a":"<div class=\"notion-course\">Les facteurs favorisants temporaires mineurs de la MTEV sont :\n<ul>\n<li><strong>Traumatisme d'un membre inférieur non plâtré</strong> avec mobilité réduite pendant au moins 3 jours (survenu il y a moins de 2 mois).</li>\n<li><strong>Immobilisation</strong> de moins de 3 jours (survenue il y a moins de 3 mois).</li>\n<li><strong>Voyage</strong> de plus de 6 heures.</li>\n<li>Traitement par <strong>Érythropoïétine (EPO)</strong>.</li>\n<li>Présence d'une <strong>voie veineuse centrale</strong>.</li>\n</ul></div>"},{"i":"0d35f50202e3","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quelle est la stratégie diagnostique face à une suspicion de maladie thrombo-embolique veineuse (MTEV) ?","a":"<div class=\"notion-course\"><ul><li>Devant une suspicion, évaluer d’abord la tolérance hémodynamique. En l’absence de choc, estimer la probabilité clinique avec un outil validé et sa version exacte.</li><li>Probabilité non forte : D-dimères dans une stratégie validée ; négatifs, exclusion possible ; positifs, imagerie. Probabilité forte : imagerie directement.</li><li><span class=\"nc-yellow_bg\">TVP</span> : échographie de compression/Doppler ; EP : angioscanner ou scintigraphie selon les contre-indications. Si imagerie négative et forte discordance clinique, poursuivre l’évaluation.</li></ul></div>"},{"i":"3218b1efd702","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quels sont les signes cliniques orientant vers une embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><ul><li>EP : <span class=\"nc-yellow_bg\">dyspnée</span>, douleur pleurale, <span class=\"nc-yellow_bg\">tachycardie</span>, <span class=\"nc-blue_bg\">hémoptysie</span>, <span class=\"nc-blue_bg nc-bold\">syncope</span> ; aucune n’est <span class=\"nc-yellow_bg\">constante</span>. Une auscultation, une gazométrie, un ECG ou une radiographie normaux ne l’excluent pas.</li></ul></div>"},{"i":"71a759db9ddb","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Comment évaluer la probabilité clinique d'une embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><ul><li><b>Scores à ne pas mélanger :</b> Wells TVP à deux niveaux : ≥ 2 probable ; Wells EP original à deux niveaux : &gt; 4 probable, ≤ 4 peu probable. Genève révisé original : 0–3 <span class=\"nc-green nc-bold\">faible</span>, 4–10 <span class=\"nc-green nc-bold\">intermédiaire</span>, ≥ 11 forte ; à deux niveaux, ≥ 6 probable. Les versions simplifiées utilisent d’autres seuils.</li></ul></div>"},{"i":"ab763f2cad8a","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Comment évaluer la probabilité clinique d'une thrombose veineuse profonde (TVP) ?","a":"<div class=\"notion-course\"><ul><li>TVP : <span class=\"nc-red nc-bold\">douleur</span>, œdème unilatéral, différence de périmètre, contexte favorisant ; le <span class=\"nc-yellow_bg\">signe de Homans</span> n’est ni fiable ni nécessaire. La phlegmatia caerulea dolens (jambe très douloureuse, cyanosée et tendue) menace le membre et nécessite une prise en charge urgente.</li><li><b>Scores à ne pas mélanger :</b> Wells TVP à deux niveaux : ≥ 2 probable ; Wells EP original à deux niveaux : &gt; 4 probable, ≤ 4 peu probable. Genève révisé original : 0–3 <span class=\"nc-green nc-bold\">faible</span>, 4–10 <span class=\"nc-green nc-bold\">intermédiaire</span>, ≥ 11 forte ; à deux niveaux, ≥ 6 probable. Les versions simplifiées utilisent d’autres seuils.</li></ul></div>"},{"i":"b7ea90ac36bb","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quels sont les signes paracliniques d'orientation pouvant être observés à l'ECG et à la radiographie thoracique (RXT) en cas d'embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><p>Les signes paracliniques d'orientation dans l'EP sont ni sensibles ni spécifiques :</p><ul><li><strong>ECG</strong> (mémo BASTON) : <ul><li><strong>B</strong>loc de branche droit</li><li><strong>A</strong>xe dévié à droite</li><li><strong>S1Q3</strong> (onde S en D1, onde Q en D3)</li><li><strong>T</strong>achycardie sinusale (le plus fréquent)</li><li><strong>O</strong>ndes T négatives de V1 à V4</li><li><strong>N</strong>ormal possible</li></ul></li><li><strong>Radiographie thoracique</strong> (RXT, mémo ABCDEF) : <ul><li><strong>A</strong>scension d'une coupole</li><li><strong>B</strong>ande d'atélectasie</li><li><strong>C</strong>larté d'un champ pulmonaire</li><li><strong>D</strong>ilatation des cavités droites</li><li><strong><span class=\"nc-orange_bg\">É</span></strong><span class=\"nc-orange_bg\">panchement pleural</span></li><li><span class=\"nc-orange_bg\">In</span><strong><span class=\"nc-orange_bg\">f</span></strong><span class=\"nc-orange_bg\">arctus pulmonaire</span></li><li>La RXT est <span class=\"nc-green nc-bold\">souvent </span><strong><span class=\"nc-green nc-bold\">normale</span></strong>.</li></ul></li><li>Une gazométrie peut montrer une <strong><span class=\"nc-yellow_bg\">hypoxémie</span></strong> associée à une <strong><span class=\"nc-yellow_bg\">hypocapnie</span></strong> (PaO₂ + PaCO₂ &lt; 120 mmHg), mais elle peut aussi être normale.</li></ul></div>"},{"i":"f93e6718814c","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quels sont les signes cliniques orientant vers une thrombose veineuse profonde (TVP) ?","a":"<div class=\"notion-course\"><ul><li>TVP : <span class=\"nc-red nc-bold\">douleur</span>, œdème unilatéral, différence de périmètre, contexte favorisant ; le <span class=\"nc-yellow_bg\">signe de Homans</span> n’est ni fiable ni nécessaire. La phlegmatia caerulea dolens (jambe très douloureuse, cyanosée et tendue) menace le membre et nécessite une prise en charge urgente.</li></ul></div>"},{"i":"64c346602108","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Comment le diagnostic d'embolie pulmonaire (EP) à haut risque est-il confirmé après l'évaluation initiale chez un patient stabilisé ?","a":"<div class=\"notion-course\"><ul><li>Angioscanner immédiatement si disponible et transport réalisable en sécurité. Sinon ETT au lit pour rechercher surcharge/dysfonction du VD et autres causes de choc. Pas de D-dimères pour décider.</li></ul></div>"},{"i":"87fbb87cadec","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Quels sont les éléments recherchés lors d'une échographie cardiaque trans-thoracique (ETT) pour diagnostiquer une embolie pulmonaire (EP) à haut risque ?","a":"<div class=\"notion-course\"><ul><li>Angioscanner immédiatement si disponible et transport réalisable en sécurité. Sinon ETT au lit pour rechercher surcharge/dysfonction du VD et autres causes de choc. Pas de D-dimères pour décider.</li><li>Si patient trop instable pour le scanner et forte suspicion <span class=\"nc-yellow_bg\">avec</span> arguments échographiques concordants, une reperfusion peut être décidée en urgence par l’équipe. L’ETT ne fournit pas à elle seule une preuve spécifique dans tous les contextes.</li><li>L’absence de surcharge droite fait rechercher une autre cause du choc ; elle n’exclut pas toutes les EP chez un patient stable.</li></ul></div>"},{"i":"cee09dd582d3","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Comment définit-on une embolie pulmonaire (EP) à haut risque chez un patient ?","a":"<div class=\"notion-course\"><ul><li>EP à haut risque = instabilité hémodynamique : arrêt cardiaque, choc obstructif ou hypotension persistante (<span class=\"nc-blue_bg\">PAS</span> <span class=\"nc-red nc-bold\">&lt; 90 mmHg</span> ou chute ≥ 40 mmHg pendant plus de 15 minutes), non expliquée par arythmie, hypovolémie ou sepsis.</li></ul></div>"},{"i":"f935c2e35e4b","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Quelle est la démarche diagnostique initiale en cas de suspicion d'embolie pulmonaire (EP) à haut risque chez un patient instable hémodynamiquement ?","a":"<div class=\"notion-course\"><ul><li>Appel réanimation/cardiologie, monitorage, oxygène si nécessaire, accès veineux et soutien hémodynamique adapté. Éviter un remplissage massif qui aggrave la défaillance droite.</li><li>Angioscanner immédiatement si disponible et transport réalisable en sécurité. Sinon ETT au lit pour rechercher surcharge/dysfonction du VD et autres causes de choc. Pas de D-dimères pour décider.</li><li>Si patient trop instable pour le scanner et forte suspicion <span class=\"nc-yellow_bg\">avec</span> arguments échographiques concordants, une reperfusion peut être décidée en urgence par l’équipe. L’ETT ne fournit pas à elle seule une preuve spécifique dans tous les contextes.</li></ul></div>"},{"i":"57d467073e34","n":226,"o":"226-6","u":"Diagnostic positif","t":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","q":"Dans quelles situations cliniques le dosage des D-dimères n'est-il PAS indiqué ou n'est-il PAS interprétable pour le diagnostic de MTEV ?","a":"<div class=\"notion-course\"><ul><li>Probabilité forte ou instabilité : imagerie directe, sans utiliser des D-dimères négatifs pour exclure.</li><li>Âge, cancer, <span class=\"nc-pink_bg\">grossesse</span>, inflammation ou chirurgie augmentent les <span class=\"nc-brown_bg nc-bold\">faux positifs</span> mais ne rendent pas le test automatiquement interdit. Pendant la <span class=\"nc-pink_bg\">grossesse</span>, employer une stratégie spécifiquement validée.</li><li>Un traitement anticoagulant préalable peut diminuer le taux et compromettre la sensibilité. Ne pas mélanger seuil ajusté à l’âge et algorithme YEARS sans suivre leur protocole respectif.</li></ul></div>"},{"i":"c10d364a7369","n":226,"o":"226-6","u":"Diagnostic positif","t":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","q":"Quel est le seuil de négativité des D-dimères pour un patient de moins de 50 ans et un patient de 70 ans dans le cadre du diagnostic d'une embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><ul><li>Pour l’EP, avec méthode exprimée en unités équivalentes fibrinogène (FEU) : seuil habituel 500 µg/L (500 ng/mL) avant 50 ans ; à partir de 50 ans, âge × 10 µg/L. À 70 ans : 700 µg/L. Vérifier méthode et unités, notamment FEU versus DDU.</li></ul></div>"},{"i":"dba75423917a","n":226,"o":"226-6","u":"Diagnostic positif","t":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","q":"Quelle est l'utilité clinique du dosage des D-dimères dans le diagnostic de la maladie thromboembolique veineuse (MTEV) ?","a":"<div class=\"notion-course\"><ul><li>Les D-dimères sont un test d’exclusion associé à une probabilité clinique <span class=\"nc-green nc-bold\">faible</span>/<span class=\"nc-green nc-bold\">intermédiaire</span> ou « peu probable », dans une stratégie validée. Un résultat positif ne prouve <span class=\"nc-red nc-bold\">pas</span> une MTEV.</li></ul></div>"},{"i":"02761f612722","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quelles sont les principales limites de l'échodoppler veineux dans le diagnostic de la thrombose veineuse profonde (TVP) ?","a":"<div class=\"notion-course\"><ul><li>L’examen peut être proximal ou complet ; sa performance est meilleure pour la <span class=\"nc-red_bg\">TVP</span> proximale que distale et dépend des conditions techniques et de l’opérateur. Une veine poplitée appartient au réseau proximal.</li><li>Si échographie proximale négative mais suspicion persistante/D-dimères positifs selon l’algorithme, prévoir une échographie répétée à environ une semaine ou une exploration complète.</li></ul></div>"},{"i":"4a9ed1d2e1bb","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quelle est la place de l'échodoppler veineux des membres inférieurs dans le diagnostic de la thrombose veineuse profonde (TVP) ?","a":"<div class=\"notion-course\"><ul><li>L’échographie de compression veineuse est l’examen de première intention d’une TVP ; signe essentiel : veine incompressible. Le Doppler précise thrombus, flux et extension.</li><li>L’examen peut être proximal ou complet ; sa performance est meilleure pour la <span class=\"nc-red_bg\">TVP</span> proximale que distale et dépend des conditions techniques et de l’opérateur. Une veine poplitée appartient au réseau proximal.</li></ul></div>"},{"i":"7510ddb8f3ac","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quelle est l'interprétation d'un échodoppler veineux des membres inférieurs dans le contexte d'une suspicion d'embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><ul><li>Dans une suspicion d’EP, identifier une TVP proximale suffit généralement à justifier un traitement de MTEV sans imposer une imagerie pulmonaire ; cela ne visualise pas directement une <span class=\"nc-red_bg\">embolie pulmonaire</span>.</li><li>Une échographie veineuse normale n’exclut pas une EP.</li></ul></div>"},{"i":"e53fcd5dbfbe","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quels sont les signes échographiques clés d'une thrombose veineuse profonde (TVP) à l'échodoppler veineux ?","a":"<div class=\"notion-course\"><ul><li>L’échographie de compression veineuse est l’examen de première intention d’une TVP ; signe essentiel : veine incompressible. Le Doppler précise thrombus, flux et extension.</li></ul></div>"},{"i":"5c29b4a08fdd","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelles sont les limites de l'échographie cardiaque trans-thoracique (ETT) pour visualiser directement l'embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>ETT : recherche du retentissement droit et stratification pronostique ; outil décisif au lit en cas de choc si scanner impossible. Une ETT normale n’exclut pas une EP stable.</li><li>Le <span class=\"nc-red nc-bold\">thrombus</span> est rarement visualisé directement en ETT ; <span class=\"nc-red nc-bold\">dilatation du VD</span>, dysfonction et <span class=\"nc-red nc-bold\">septum paradoxal</span> ne sont pas spécifiques à eux seuls. L’angiographie invasive n’est pas l’examen diagnostique de routine.</li></ul></div>"},{"i":"7d0f9ac3ea1e","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelle est la principale limite de la scintigraphie de ventilation-perfusion dans le diagnostic de l'embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>Scintigraphie ventilation/perfusion : alternative notamment si le contraste est inapproprié. Une perfusion normale exclut l’EP ; des défauts de perfusion sans défaut ventilatoire correspondant sont évocateurs. Un résultat indéterminé exige des examens complémentaires.</li></ul></div>"},{"i":"a6288d5e4fdf","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelles sont les principales limites de l'angio-TDM thoracique pour le diagnostic de l'embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>Angioscanner pulmonaire : recherche d’une lacune endovasculaire dans les artères pulmonaires ; évalue aussi le VD et certains diagnostics différentiels. Adapter en cas d’insuffisance rénale, antécédent de réaction au contraste ou grossesse.</li><li>Une imagerie positive doit être interprétée avec la qualité technique et la probabilité clinique, particulièrement pour une anomalie sous-segmentaire isolée. Une imagerie négative discordante avec une <span class=\"nc-green nc-bold\">forte</span> probabilité nécessite une réévaluation.</li></ul></div>"},{"i":"c2e4d85ab907","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quand la scintigraphie de ventilation-perfusion est-elle indiquée dans le diagnostic de l'embolie pulmonaire et comment est-elle interprétée selon la classification PIOPED ?","a":"<div class=\"notion-course\"><ul><li>Scintigraphie ventilation/perfusion : alternative notamment si le contraste est inapproprié. Une perfusion normale exclut l’EP ; des défauts de perfusion sans défaut ventilatoire correspondant sont évocateurs. Un résultat indéterminé exige des examens complémentaires.</li></ul></div>"},{"i":"c9d843896ffb","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quel est le rôle de l'échographie cardiaque trans-thoracique (ETT) dans le diagnostic et la prise en charge de l'embolie pulmonaire (EP) ?","a":"<div class=\"notion-course\"><ul><li>ETT : recherche du retentissement droit et stratification pronostique ; outil décisif au lit en cas de choc si scanner impossible. Une ETT normale n’exclut pas une EP stable.</li><li>Le <span class=\"nc-red nc-bold\">thrombus</span> est rarement visualisé directement en ETT ; <span class=\"nc-red nc-bold\">dilatation du VD</span>, dysfonction et <span class=\"nc-red nc-bold\">septum paradoxal</span> ne sont pas spécifiques à eux seuls. L’angiographie invasive n’est pas l’examen diagnostique de routine.</li></ul></div>"},{"i":"d32190746790","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelle est la place de l'angio-TDM thoracique dans le diagnostic de l'embolie pulmonaire (EP) et quels sont ses critères de positivité ?","a":"<div class=\"notion-course\"><ul><li>Angioscanner pulmonaire : recherche d’une lacune endovasculaire dans les artères pulmonaires ; évalue aussi le VD et certains diagnostics différentiels. Adapter en cas d’insuffisance rénale, antécédent de réaction au contraste ou grossesse.</li><li>Une imagerie positive doit être interprétée avec la qualité technique et la probabilité clinique, particulièrement pour une anomalie sous-segmentaire isolée. Une imagerie négative discordante avec une <span class=\"nc-green nc-bold\">forte</span> probabilité nécessite une réévaluation.</li></ul></div>"},{"i":"10931fe6b6f5","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les six critères du score sPESI pour évaluer la gravité d'une embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>Chez le patient stable, sPESI : un point pour <span class=\"nc-blue_bg\">âge</span> &gt; 80 ans, <span class=\"nc-orange_bg\">cancer</span>, maladie cardiaque ou respiratoire chronique, FC ≥ 110/min, <span class=\"nc-blue_bg\">PAS</span> &lt; 100 mmHg, SpO₂ &lt; 90 %. Ce score est pronostique, <span class=\"nc-blue_bg\">pas</span> diagnostique.</li></ul></div>"},{"i":"295fe9fa2b05","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les trois plans d'évaluation de la gravité d'une embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>Commencer par l’hémodynamique : une instabilité définit le haut risque et appelle la stratégie de reperfusion.</li><li>Chez le patient stable, sPESI : un point pour <span class=\"nc-blue_bg\">âge</span> &gt; 80 ans, <span class=\"nc-orange_bg\">cancer</span>, maladie cardiaque ou respiratoire chronique, FC ≥ 110/min, <span class=\"nc-blue_bg\">PAS</span> &lt; 100 mmHg, SpO₂ &lt; 90 %. Ce score est pronostique, <span class=\"nc-blue_bg\">pas</span> diagnostique.</li><li>Associer l’évaluation du VD par ETT ou scanner et la troponine. Une atteinte du VD et une troponine positive chez un patient de risque clinique accru définissent le risque <span class=\"nc-green nc-bold\">intermédiaire</span> élevé : surveillance hospitalière rapprochée, sans thrombolyse systématique en l’absence de dégradation.</li></ul></div>"},{"i":"2e4af7d0a842","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les signes de souffrance du ventricule droit (VD) à rechercher pour évaluer la gravité d'une embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>Associer l’évaluation du VD par ETT ou scanner et la troponine. Une atteinte du VD et une troponine positive chez un patient de risque clinique accru définissent le risque <span class=\"nc-green nc-bold\">intermédiaire</span> élevé : surveillance hospitalière rapprochée, sans thrombolyse systématique en l’absence de dégradation.</li></ul></div>"},{"i":"31270044e512","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les critères permettant d'envisager une prise en charge ambulatoire pour une embolie pulmonaire ?","a":"<div class=\"notion-course\"><ul><li>Faible risque : outils validés (sPESI/PESI ou Hestia), absence d’élément défavorable, risque hémorragique acceptable et traitement réalisable. L’ambulatoire exige compréhension, soutien, accès au traitement et suivi rapide.</li><li>Un score rassurant n’annule pas une hypoxémie, une douleur incontrôlée, une dysfonction droite ou une difficulté sociale. Hestia est une liste d’exclusion de l’ambulatoire, à appliquer dans sa version complète.</li></ul></div>"},{"i":"50026952839e","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Comment définit-on la gravité hémodynamique d'une embolie pulmonaire dite « à haut risque » ?","a":"<div class=\"notion-course\"><ul><li>EP à haut risque = instabilité hémodynamique : arrêt cardiaque, choc obstructif ou hypotension persistante (<span class=\"nc-blue_bg\">PAS</span> <span class=\"nc-red nc-bold\">&lt; 90 mmHg</span> ou chute ≥ 40 mmHg pendant plus de 15 minutes), non expliquée par arythmie, hypovolémie ou sepsis.</li></ul></div>"},{"i":"ad67be39f6f4","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Dans quels cas une embolie pulmonaire impose-t-elle impérativement une hospitalisation ?","a":"<div class=\"notion-course\"><ul><li>Commencer par l’hémodynamique : une instabilité définit le haut risque et appelle la stratégie de reperfusion.</li><li>Associer l’évaluation du VD par ETT ou scanner et la troponine. Une atteinte du VD et une troponine positive chez un patient de risque clinique accru définissent le risque <span class=\"nc-green nc-bold\">intermédiaire</span> élevé : surveillance hospitalière rapprochée, sans thrombolyse systématique en l’absence de dégradation.</li><li>Un score rassurant n’annule pas une hypoxémie, une douleur incontrôlée, une dysfonction droite ou une difficulté sociale. Hestia est une liste d’exclusion de l’ambulatoire, à appliquer dans sa version complète.</li></ul></div>"},{"i":"bf432e1cdcb6","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les six critères du sPESI et leur seuil exact ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Âge</span> &gt; 80 ans ; <span class=\"nc-orange_bg\">cancer</span> ; <span class=\"nc-orange_bg\">insuffisance</span> cardiaque ou respiratoire chronique ; FC ≥ 110/min ; <span class=\"nc-blue_bg\">PAS</span> &lt; 100 mmHg ; SpO₂ &lt; 90 %. Un point chacun.</li></ul></div>"},{"i":"82fe9a344cb9","n":226,"o":"226-3","u":"Physiopathologie","t":"Connaître la physiopathologie de la MTEV y compris les formes familiales","q":"Quels sont les points clés concernant la physiopathologie de la MTEV y compris les formes familiales ?","a":"<div class=\"notion-course\"><ul><li>La constitution du <span>thrombus</span> repose sur la <span>triade de Virchow</span> : <strong><span><span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">stase veineuse</span></span></span></strong> + <strong><span>lésion pariétale</span></strong> + <strong><span><span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">anomalies de l'hémostase</span></span></span></strong> (hypercoagulabilité). Le point de départ est souvent <strong>distal</strong>, dans les zones de ralentissement du flux (<span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">veines soléaires</span></span>, <span class=\"nc-blue_bg\"><span class=\"nc-blue_bg\">valvules</span></span>, abouchement des collatérales).</li><li><strong>Lien <span>TVP</span> → EP.</strong> La plupart des thrombi fibrino-cruoriques proviennent des veines profondes des MI et du pelvis : l'<span>EP est secondaire à une TVP dans 70 %</span> <span class=\"nc-red_bg\"><span class=\"nc-red_bg\">des cas</span></span>, survenant <span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\">3 à 7 jours</span></span></span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\"> après</span></span>. Environ <span>50 %</span> des patients porteurs d'une <span>TVP</span> proximale ont une EP, y compris asymptomatique.</li><li><strong>Formes familiales.</strong> Les <span>thrombophilies héréditaires</span> sont retrouvées chez environ 1/4 des patients, mais leur impact clinique est <span class=\"nc-green nc-bold\"><span class=\"nc-green nc-bold\">faible</span></span> — sauf le déficit en antithrombine.</li><li><span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">Déficit en antithrombine</span></span></span> — facteur <span>héréditaire</span> le <strong>plus thrombogène</strong>, même à l'état hétérozygote, mais le plus rare.</li></ul></div>"},{"i":"db3f60a41002","n":226,"o":"226-14","u":"Prise en charge","t":"Savoir déterminer la durée du traitement anticoagulant (TVP proximale et EP)","q":"Comment déterminer la durée du traitement anticoagulant (TVP proximale et EP) ?","a":"<div class=\"notion-course\"><ul><li>TVP proximale ou EP : au moins trois mois de traitement dans la majorité des cas, puis décision explicite de poursuite ou d’arrêt.</li><li>Premier événement provoqué par un facteur <span class=\"nc-green_bg\">transitoire majeur</span> disparu : trois mois suffisent souvent. Ne pas prolonger uniquement parce que le scanner initial montrait de nombreux caillots.</li><li>Événement non provoqué, récidive ou facteur persistant : discuter un traitement prolongé, voire sans date de fin prédéfinie, selon risque de récidive et de saignement, préférences et tolérance.</li><li><span class=\"nc-red_bg\">Cancer actif</span> : traitement au moins plusieurs mois et réévaluation tant que le <span class=\"nc-orange nc-bold\">cancer</span> ou son traitement reste actif. <span class=\"nc-red_bg\">SAPL</span> à haut risque : stratégie spécifique, souvent <span class=\"nc-pink_bg\">AVK</span>.</li></ul></div>"},{"i":"0719c1fc3297","n":226,"o":"226-15","u":"Étiologies","t":"Savoir porter l’indication d’une recherche de cancer en cas de MTEV (TVP, EP)","q":"Comment porter l’indication d’une recherche de cancer en cas de MTEV (TVP, EP) ?","a":"<div class=\"notion-course\"><ul><li>Une MTEV non provoquée peut révéler un <span class=\"nc-orange_bg\">cancer</span>. Rechercher signes fonctionnels, amaigrissement, examen anormal et anomalies biologiques ; revoir antécédents et dépistages recommandés pour l’âge et le sexe.</li><li>Bilan initial limité : interrogatoire/examen complets et biologie de base, puis examens ciblés selon les anomalies. Ne pas attendre un <span class=\"nc-red nc-bold\">bilan de thrombophilie négatif</span> pour rechercher un symptôme évocateur.</li><li>Pas de scanner corps entier, TEP, marqueurs tumoraux, <span class=\"nc-pink nc-bold\">PSA</span>, <span class=\"nc-pink nc-bold\">échographie pelvienne</span> ou endoscopie systématiques uniquement du fait de la MTEV en l’absence d’orientation.</li><li>Informer sur les symptômes nouveaux et assurer le suivi. Le risque de <span class=\"nc-orange nc-bold\">cancer</span> varie selon la population ; une large fourchette historique de 6 à 28 % ne s’applique <span class=\"nc-red nc-bold\">pas</span> à chaque première MTEV.</li></ul></div>"},{"i":"bddf575773e4","n":226,"o":"226-16","u":"Suivi et/ou pronostic","t":"Savoir évoquer les complications à long terme de la MTEV (syndrome post-thrombotique, HTAP)","q":"Comment évoquer les complications à long terme de la MTEV (syndrome post-thrombotique, HTAP) ?","a":"<div class=\"notion-course\"><ul><li>Deux complications tardives sont à connaître, l'une veineuse après <span>TVP</span>, l'autre artérielle pulmonaire après EP.</li><li><em>📎 Items liés : 227 — Insuffisance veineuse chronique - varices</em></li><li>Le syndrome post-thrombotique peut apparaître dès les premiers mois, et non uniquement à cinq ou dix ans. L’HTP thromboembolique chronique relève d’un centre expert ; le traitement peut associer endartériectomie, angioplastie pulmonaire et traitement médical selon l’opérabilité.</li></ul></div>"},{"i":"0014a51e8b10","n":226,"o":"226-17","u":"Suivi et/ou pronostic","t":"Connaître la complication à dépister avant d’arrêter un traitement anticoagulant pour EP","q":"Quels sont les points clés concernant la complication à dépister avant d’arrêter un traitement anticoagulant pour EP ?","a":"<div class=\"notion-course\"><ul><li>La complication à dépister avant d'arrêter une <span>anticoagulation</span> prescrite pour EP est l'<span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">hypertension pulmonaire post-embolique</span></span> (HTP-PE)</span> — rare (<span>2-3 %</span>) mais grave, liée à la persistance d'une obstruction significative du lit artériel pulmonaire.</li><li><strong>Signe d'appel :</strong> une <span>dyspnée persistante</span> à distance de l'EP, <span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">&gt; </span></span><span><span class=\"nc-yellow_bg\"><span class=\"nc-yellow_bg\">3 mois</span></span></span> après le traitement.</li><li><span>ETT</span> : estimation de la PAP systolique et recherche de signes indirects (dilatation et dysfonction du VD).</li><li>Si <span><span class=\"nc-red nc-bold\"><span class=\"nc-red nc-bold\">PAPs élevée</span></span></span> ou risque échographique d'HTAP intermédiaire/élevé → <span>scintigraphie de ventilation-perfusion</span>.</li></ul></div>"},{"i":"89fcac8cd990","n":226,"o":"226-18","u":"Prise en charge","t":"Connaître les principes de la prise en charge une thrombose veineuse superficielle","q":"Quels sont les points clés concernant les principes de la prise en charge une thrombose veineuse superficielle ?","a":"<div class=\"notion-course\"><ul><li>TVS : cordon superficiel rouge, induré et douloureux. Réaliser un écho-Doppler pour mesurer l’extension, la distance à la jonction profonde et rechercher une TVP associée ; elle n’est pas toujours bénigne.</li><li>TVP associée ou TVS très proche du réseau <span class=\"nc-yellow_bg\">profond</span> (repère ≤ 3 cm de la jonction) : évaluation pour anticoagulation à dose curative selon protocole spécialisé.</li><li>TVS d’au moins 5 cm, à distance de la jonction profonde : <span class=\"nc-pink_bg\">fondaparinux</span> 2,5 mg/j pendant <span class=\"nc-pink nc-bold\">45 jours</span> classiquement, si fonction rénale et risque hémorragique compatibles ; alternatives selon recommandations.</li><li>TVS courte à faible risque : traitement symptomatique et surveillance ; anticoagulation discutée si <span class=\"nc-brown_bg\">facteurs</span> de risque ou progression. Éviter les AINS systémiques associés sans réflexion à une anticoagulation.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181649937ef8cb0b5ce38?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
